package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string
	ErDept  string
	ErHours decimal.Decimal
	ErRate  decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.Zero
var WsOtHours decimal.Decimal = decimal.Zero
var WsGross decimal.Decimal = decimal.Zero
var WsDeptTotal decimal.Decimal = decimal.Zero
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.Zero
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var curEmp EmpRec
var empLines []string
var empIdx int
var empOpened bool
var inputDone bool = false

func isInputDone() bool { return inputDone }
func setInputDone()    { inputDone = true; WsEofFlag = "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func pow10(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func maskToField(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	m := pow10(intDigits + scale)
	s := v.Shift(int32(scale)).Truncate(0)
	r := s.Mod(m)
	return r.Shift(int32(-scale))
}

func storeTrunc(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	t := v.Truncate(int32(scale))
	return maskToField(t, intDigits, scale)
}

func storeRound(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	r := v.Round(int32(scale))
	return maskToField(r, intDigits, scale)
}

func storeCount(v int64, digits int) int64 {
	m := int64(1)
	for i := 0; i < digits; i++ {
		m *= 10
	}
	r := v % m
	if r < 0 {
		r += m
	}
	return r
}

func parseNumField(s string, scale int) decimal.Decimal {
	if len(s) == 0 {
		return decimal.Zero
	}
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else if c == '.' {
			continue
		} else if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, int32(-scale))
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatCount(v int64, digits int) string {
	neg := false
	if v < 0 {
		neg = true
		v = -v
	}
	s := fmt.Sprintf("%d", v)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	if neg {
		// COBOL would show sign; keep simple
		if len(s) > 0 {
			s = "-" + s[1:]
		}
	}
	return s
}

func formatEdited(v decimal.Decimal, pic string) string {
	dot := strings.Index(pic, ".")
	var intPic, fracPic string
	if dot >= 0 {
		intPic = pic[:dot]
		fracPic = pic[dot+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	scale := len(fracPic)
	// truncate/round to scale: MOVE uses truncate; values already exact
	t := v.Truncate(int32(scale))
	neg := t.Sign() < 0
	absV := t.Abs()
	scaled := absV.Shift(int32(scale)).Truncate(0)
	fracInt := int64(0)
	intPart := scaled
	if scale > 0 {
		m := pow10(scale)
		fracDec := scaled.Mod(m)
		fracInt = fracDec.IntPart()
		intPart = scaled.Div(m).Truncate(0)
	}
	// count integer digit slots
	intDigitCount := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			intDigitCount++
		}
	}
	// integer digits low-order
	intStr := intPart.String()
	// intPart is integer decimal; get digits
	// intStr may be like "1234"
	if strings.Contains(intStr, ".") {
		intStr = strings.Split(intStr, ".")[0]
	}
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	if intStr == "" {
		intStr = "0"
	}
	// keep low-order
	if len(intStr) > intDigitCount {
		intStr = intStr[len(intStr)-intDigitCount:]
	}
	// left pad with zeros to intDigitCount
	if len(intStr) < intDigitCount {
		intStr = strings.Repeat("0", intDigitCount-len(intStr)) + intStr
	}
	digits := []byte(intStr)
	// build integer part
	var outInt []byte
	suppressed := true
	di := 0
	// need to know for comma handling: suppressed means no significant digit yet
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			d := digits[di]
			di++
			if c == '9' {
				outInt = append(outInt, d)
				suppressed = false
			} else {
				if suppressed && d == '0' {
					// check if all remaining int digits are zero and remaining slots are Z?
					// Standard: suppress this zero; but if this is last digit slot and all zero, still suppress (9 will print)
					// Since this is Z, suppress.
					outInt = append(outInt, ' ')
				} else if suppressed && d != '0' {
					outInt = append(outInt, d)
					suppressed = false
				} else {
					outInt = append(outInt, d)
				}
			}
		} else if c == ',' {
			if suppressed {
				outInt = append(outInt, ' ')
			} else {
				outInt = append(outInt, ',')
			}
		} else {
			outInt = append(outInt, c)
		}
	}
	var out []byte
	out = append(out, outInt...)
	if dot >= 0 {
		out = append(out, '.')
		fracStr := fmt.Sprintf("%0*d", scale, fracInt)
		if len(fracStr) > scale && scale > 0 {
			fracStr = fracStr[len(fracStr)-scale:]
		}
		out = append(out, []byte(fracStr)...)
	}
	_ = neg
	return string(out)
}

func MAINPARA() {
	OPENINPUT()
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if !isFirstRecord() {
		DEPTBREAKPARA()
	}
	CLOSEEMP()
	GRANDPARA()
}

func OPENINPUT() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			empLines = nil
			empIdx = 0
			empOpened = true
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	var lines []string
	for sc.Scan() {
		line := sc.Text()
		if strings.HasSuffix(line, "\r") {
			line = line[:len(line)-1]
		}
		lines = append(lines, line)
	}
	empLines = lines
	empIdx = 0
	empOpened = true
}

func CLOSEEMP() {
	empOpened = false
}

func READPARA() {
	if !empOpened {
		setInputDone()
		return
	}
	if empIdx >= len(empLines) {
		setInputDone()
		return
	}
	line := empLines[empIdx]
	empIdx++
	// pad to 17
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	curEmp.ErId = line[0:5]
	curEmp.ErDept = line[5:8]
	curEmp.ErHours = parseNumField(line[8:12], 1)
	curEmp.ErRate = parseNumField(line[12:17], 2)
}

func PROCESSPARA() {
	if isFirstRecord() {
		WsPrevDept = curEmp.ErDept
		WsFirstFlag = "N"
	} else {
		if curEmp.ErDept != WsPrevDept {
			DEPTBREAKPARA()
			WsPrevDept = curEmp.ErDept
		}
	}
	PAYPARA()
	READPARA()
}

func PAYPARA() {
	forty := decimal.NewFromInt(40)
	if curEmp.ErHours.Cmp(forty) > 0 {
		WsRegHours = storeTrunc(decimal.NewFromInt(40), 3, 1)
		WsOtHours = storeTrunc(curEmp.ErHours.Sub(forty), 3, 1)
	} else {
		WsRegHours = storeTrunc(curEmp.ErHours, 3, 1)
		WsOtHours = storeTrunc(decimal.Zero, 3, 1)
	}
	oneHalf := decimal.New(15, -1)
	expr := WsRegHours.Mul(curEmp.ErRate).Add(WsOtHours.Mul(curEmp.ErRate).Mul(oneHalf))
	WsGross = storeRound(expr, 7, 2)
	WsDeptTotal = maskToField(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = storeCount(WsDeptCount+1, 3)
	WsGrandTotal = maskToField(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = storeCount(WsGrandCount+1, 5)
	WsHoursEd = formatEdited(curEmp.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(curEmp.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", curEmp.ErId, curEmp.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DEPTBREAKPARA() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, formatCount(WsDeptCount, 3), WsDeptEd)
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
}

func GRANDPARA() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("GRAND TOTAL (%s): %s\n", formatCount(WsGrandCount, 5), WsGrandEd)
}

func main() {
	_ = padRight
	MAINPARA()
}
